Given an array of integers arr[] representing a permutation (i.e., all elements are unique and arranged in some order), find the next lexicographically greater permutation by rearranging the elements of the array.If such a permutation does not exist (i.e., the array is the last possible permutation), rearrange the elements to form the lowest possible order (i.e., sorted in ascending order).Examples:Input: arr[] = [2, 4, 1, 7, 5, 0]Output: [2, 4, 5, 0, 1, 7]Explanation: The next lexicographically greater arrangement of the elements in the array arr[] is [2, 4, 5, 0, 1, 7].Input: arr[] = [3, 2, 1]Output: [1, 2, 3]Explanation: This is the last permutation, so we return the lowest possible permutation (ascending order).Input: arr[] = [1, 3, 5, 4, 2]Output: [1, 4, 2, 3, 5]Explanation: The next lexicographically greater arrangement of the elements in the array arr[] is [1, 4, 2, 3, 5].Try It YourselfTable of Content[Naive Approach] Generate All Permutations - O(n! * n) Time and O(n! * n) Space[Expected Approach] Generating Only Next - O(n) Time and O(1) Space[Alternate Approach in C++] Using Inbuilt Function - O(n) Time and O(1) Space [Naive Approach] Generate All Permutations - O(n! * n) Time and O(n! * n) SpaceThe idea is that we would first generate all possible permutations of a given array and sort them. Once sorted, we locate the current permutation within this list. The next permutation is simply the next arrangement in the sorted order. If the current arrangement is the last in the list then display the first permutation (smallest permutation).
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void generatePermutations(vector<vector<int>> &res, 
                          vector<int> &arr, int idx) {

    // Base case: if idx reaches the end of array
    if (idx == arr.size() - 1) {
        res.push_back(arr);
        return;
    }

    // Generate all permutations by swapping
    for (int i = idx; i < arr.size(); i++) {
        swap(arr[idx], arr[i]);

        // Recur for the next index
        generatePermutations(res, arr, idx + 1);

        // Backtrack to restore original array
        swap(arr[idx], arr[i]);
    }
}

// Function to find the next permutation
void nextPermutation(vector<int>& arr) {

    vector<vector<int>> res;

    // Generate all permutations
    generatePermutations(res, arr, 0);

    // Sort all permutations lexicographically
    sort(res.begin(), res.end());

    // Find the current permutation index
    for (int i = 0; i < res.size(); i++) {

        // If current permutation matches input
        if (res[i] == arr) {

            // If it's not the last permutation
            if (i < res.size() - 1) {
                arr = res[i + 1];
            }

            // If it's the last permutation
            else {
                arr = res[0];
            }

            break;
        }
    }
}

int main() {

    vector<int> arr = {2, 4, 1, 7, 5, 0};

    nextPermutation(arr);

    for (int i = 0; i < arr.size(); i++) {
        cout << arr[i] << " ";
    }

    return 0;
}


